const fix=document.createElement('style');fix.textContent='.modes{grid-template-columns:repeat(3,minmax(0,1fr))}.modes button{min-width:0;padding-left:2px;padding-right:2px}nav{width:100%;grid-template-columns:repeat(4,minmax(0,1fr))}nav button{min-width:0}';document.head.append(fix);
const ss=[...document.querySelectorAll('.screen')],tabs=[...document.querySelectorAll('nav button')];let stack=['home'],playing=false;function go(id,p=true){ss.forEach(s=>s.classList.toggle('active',s.dataset.screen===id));tabs.forEach(t=>t.classList.toggle('on',t.dataset.go===id));document.querySelector('nav').hidden=['call','quiet'].includes(id);if(p&&stack.at(-1)!==id)stack.push(id)}document.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>go(b.dataset.go));document.querySelectorAll('[data-back]').forEach(b=>b.onclick=()=>{stack.pop();go(stack.at(-1)||'home',false)});document.querySelectorAll('[data-play]').forEach(b=>b.onclick=()=>{playing=!playing;document.querySelectorAll('[data-play]').forEach(x=>x.textContent=playing?'Ⅱ':'▶');toast(playing?'正在播放 · 晚风':'音乐已暂停')});document.querySelectorAll('.chips button,.voices button').forEach(b=>b.onclick=()=>{[...b.parentElement.children].forEach(x=>x.classList.remove('on'));b.classList.add('on');toast('设置已更新')});scene.onclick=()=>toast('环境音已切换为「夜雨」');privacy.onclick=()=>toast('所有记忆都由你确认和管理');chatForm.onsubmit=e=>{e.preventDefault();let v=chatInput.value.trim();if(!v)return;messages.insertAdjacentHTML('beforeend',`<div class="msg me"><p>${v.replace(/[<>]/g,'')}</p></div>`);chatInput.value='';messages.scrollTop=messages.scrollHeight;setTimeout(()=>{messages.insertAdjacentHTML('beforeend','<div class="msg bot"><i>⌣</i><p>我在。我们可以慢慢说，也可以先听一会儿歌。</p></div>');messages.scrollTop=messages.scrollHeight},500)};let tm;function toast(x){let t=document.querySelector('.toast');t.textContent=x;t.classList.add('show');clearTimeout(tm);tm=setTimeout(()=>t.classList.remove('show'),1800)}
